import{_ as a,c as t,a as r,o as i}from"./app-C_dHcy8Q.js";const o={};function c(d,e){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="tracing-trace-id-propagation" tabindex="-1"><a class="header-anchor" href="#tracing-trace-id-propagation"><span>Tracing &amp; Trace ID Propagation</span></a></h1><p>Croupier propagates a lightweight <code>trace_id</code> across the Server → Agent → Adapter chain. This helps correlate UI/API calls, audit events, and downstream requests.</p><p>Flow</p><ul><li>Server (HTTP): generates a random <code>trace_id</code> per request and records it in audit; forwards it via <code>InvokeRequest.metadata[&quot;trace_id&quot;]</code>.</li><li>Agent/Server routing: preserves request metadata (trace_id/game_id/env) on RPC to function handlers.</li><li>Adapters (HTTP/Prom): add <code>X-Trace-Id</code>, <code>X-Game-Id</code>, <code>X-Env</code> headers to outbound HTTP requests when not already present.</li></ul><p>Headers</p><ul><li><code>X-Trace-Id</code>: correlates downstream REST requests with the originating GM action.</li><li><code>X-Game-Id</code>, <code>X-Env</code>: scope hints for multi-game environments (optional).</li></ul><p>UI</p><ul><li><code>/gm/audit</code>（或相关页面）中可查看 <code>trace_id</code> 字段；服务端日志也会打印 <code>trace_id</code>。</li></ul><p>Future Work</p><ul><li>OTLP exporter for distributed tracing (Jaeger/Tempo/etc.): planned. The existing <code>trace_id</code> can be embedded into spans once enabled.</li></ul>',10)])])}const s=a(o,[["render",c]]),l=JSON.parse('{"path":"/tracing.html","title":"Tracing & Trace ID Propagation","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1762002341000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"228147054e4f1a15cada6bb3a8af42c4128040fb","time":1762002341000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: commit local changes"}]},"filePathRelative":"tracing.md"}');export{s as comp,l as data};
